HERO_STR_STATIC(hero_str_1d47c8, "ok ");
HERO_STR_STATIC(hero_str_1080, "  ");
HERO_STR_STATIC(hero_str_48d7c7ce, "The Zen of Heroes\n\n 1. This language begins with a tribute to David Bowie.\n 2. It is made for language models; people can read it too.\n 3. A model may have read everything; each page must still explain itself.\n 4. What the eye can see is all there is: sound and vision.\n 5. There is one way to say each thing; every program sings in the same voice.\n 6. That way may not be obvious at first; the Starman already knows it.\n 7. The semantics are familiar; the syntax is new.\n 8. Turn and face the strange: every strange choice here is deliberate.\n 9. Nothing changes behind your back; every change signs its name.\n10. Every plausible mistake must become a compile error before the program runs.\n11. Unless you mark the unfinished place with ???.\n12. An honest hole beats a confident guess.\n13. A compile-time error is an answer; a runtime error is an ambush.\n14. An error should tell you how to fix the program. Anything less is a complaint.\n15. Repeating a word is cheap; forgetting one can cost the whole program.\n16. The specification stays small under pressure; every word must earn its place.\n17. Crashes and leaks are bugs. Ashes to ashes: what Heroes takes, it returns.\n18. When pretty code and safe code disagree, safe code wins.\n19. There is no standard library; C is the man who sold the world.\n20. We can be heroes, just for one day.\n");
HERO_STR_STATIC(hero_str_7708a7f0, "heroes \342\200\224 the Heroes compiler\n\nusage: heroes <command> [file] [flags]\n\n");
HERO_STR_STATIC(hero_str_3d01a70e, " <file.hero>");
HERO_STR_STATIC(hero_str_b006e50, " [file]");
HERO_STR_STATIC(hero_str_358cd22b, "\n      ");
HERO_STR_STATIC(hero_str_4474153b, " <path>");
HERO_STR_STATIC(hero_str_26925fc3, "      ");
HERO_STR_STATIC(hero_str_66c37b63, "\n  --version \302\267 --help\n\n");
HERO_STR_STATIC(hero_str_3f2095f9, "streams: the artifact on stdout, diagnostics and progress on stderr.\n");
HERO_STR_STATIC(hero_str_642a774c, "exit:    0 nothing to report \302\267 1 diagnostics were reported, no artifact was produced\n");
HERO_STR_STATIC(hero_str_726678f4, "         2 the tool could not run. `run` forwards the program's own status.\n");
HERO_STR_STATIC(hero_str_1db0a85c, "env:     HEROES_RUNTIME  where heroes_runtime.h and runtime.c live, if not\n");
HERO_STR_STATIC(hero_str_eaa1c49, "         under the working directory or beside the compiler.\n\n");
HERO_STR_STATIC(hero_str_723f7597, "Commands not built yet: lsp \302\267 cc\n");
